const $ = s => document.querySelector(s);
const scrollRoot=()=>document.getElementById('app');
let scrollingUntil=0,renderAfterScroll=null,restoringScroll=false;
function resetPageScroll(){scrollRoot().scrollTop=0;}
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon = {collection:'▦',decks:'▤',battle:'⚔',boards:'✧',rules:'◈'};
const KEY='anime-clash-v1';
const load = (key,fallback) => {try {return JSON.parse((localStorage.getItem(`${KEY}-${key}`)??'null').replaceAll('Hidden Leaf Village','Naruto').replaceAll('Straw Hat Pirates','One Piece')) ?? fallback;}catch{return fallback;}};
const save = (key,data) => {try{localStorage.setItem(`${KEY}-${key}`,JSON.stringify(data));}catch{toast('Browser storage is full. Your current session still works.');}};
let faction=load('faction',LEAF);
if(!PLAYABLE_FACTIONS.includes(faction))faction=LEAF;
const deckBooks=load('decks',{});
let tgHero=load('tg-hero','kaneki'),heroPathView=null;
if(Array.isArray(deckBooks[TOKYO_GHOUL])){const migrated=separateLegacyHero(deckBooks[TOKYO_GHOUL],tgHero);if(migrated.removed){deckBooks[TOKYO_GHOUL]=migrated.deck;tgHero=migrated.hero;save('decks',deckBooks);save('tg-hero',tgHero);}}

let deck=deckBooks[faction]??(faction===LEAF?load('deck',FACTION_LISTS[LEAF]):FACTION_LISTS[faction]);
if(!Array.isArray(deck)||deck.some(id=>!FACTION_POOLS[faction].includes(id)))deck=[...FACTION_LISTS[faction]];
let savedDecks=normalizeDecks(load('saved-decks',[])),activeDeck=load('active-deck',null),showBattleSetup=false,deckNameDraft=savedDecks.find(d=>d.id===activeDeck)?.name??`${faction} deck`;
if(!savedDecks.length){for(const [f,cards] of Object.entries({...deckBooks,[faction]:deck})){if(PLAYABLE_FACTIONS.includes(f)&&Array.isArray(cards))savedDecks=saveDeck(savedDecks,{name:`Your ${f} deck`,faction:f,cards,hero:tgHero},crypto.randomUUID());}save('saved-decks',savedDecks);}
let presets=ANIME_PRESETS[faction],collection=FACTION_POOLS[faction].map(getCard),deckListOpen=window.innerWidth>640,zoomUnit=null;
function selectedTGHero(){return TG_HEROES[tgHero]?tgHero:'kaneki';}
function heroChooser(){return faction===TOKYO_GHOUL?heroPickerHTML({choice:selectedTGHero(),path:heroPathView,needsCard:deck.length===29}):'';}
function heroReady(){return faction!==TOKYO_GHOUL||heroPathView==null||heroPathView===TG_HEROES[selectedTGHero()].path;}
function commitHero(plan){deck=[...plan.deck];tgHero=plan.key;heroPathView=TG_HEROES[plan.key].path;save('tg-hero',tgHero);persistDeck();render(true);toast(`${TG_HEROES[tgHero].name} selected as your Hero.`);}
function chooseTGHero(key){if(TG_HEROES[key])commitHero(heroSelectionPlan(deck,key));}
function fillHeroSlot(){
 if(deck.length!==29)return;const ct=counts(),choices=FACTION_POOLS[TOKYO_GHOUL].filter(id=>(ct[id]??0)<copyLimit(id));
 const shade=document.createElement('div');shade.className='modal-shade hero-swap-shade';
 shade.innerHTML=`<section class="modal hero-swap-modal" role="dialog" aria-modal="true" aria-label="Complete your deck"><h2>Choose your 30th playable card</h2><p>Your Hero is selected separately. Choose a card to fill the freed slot.</p><div class="hero-swap-options">${choices.map(id=>`<button data-hero-fill="${id}"><span>${getCard(id).cost}</span>${esc(getCard(id).name)}<small>Add one copy</small></button>`).join('')}</div><button class="ghost" data-cancel-hero>Cancel</button></section>`;
 shade.querySelector('[data-cancel-hero]').onclick=()=>shade.remove();shade.onclick=e=>{if(e.target===shade)shade.remove();};shade.addEventListener('keydown',e=>{if(e.key==='Escape')shade.remove();});
 shade.querySelectorAll('[data-hero-fill]').forEach(el=>el.onclick=()=>{deck.push(el.dataset.heroFill);shade.remove();persistDeck();render(true);toast('Deck complete: 30 playable cards plus your Hero.');});document.body.append(shade);shade.querySelector('[data-hero-fill]')?.focus({preventScroll:true});
}

const FACTION_META={
 [TOKYO_GHOUL]:{badge:'◈',short:'Tokyo Ghoul',title:'Hunger in the Shadows',headline:'Embrace your <em>Hunger.</em>',anime:'TOKYO GHOUL',ink:'喰種',description:'Choose a Ghoul or Investigator Hero. Master your Kagune, or hunt with the CCG.',portrait:'art/tokyo-ghoul/kaneki-hero.webp',rival:'art/tokyo-ghoul/arima.webp',back:'art/tokyo-ghoul/masked.webp',hero:'tg_predatory_instinct',troop:'Minions',spell:'Spells',exp:'03'},
 [LEAF]:{badge:'🍃',short:'Naruto',title:'The Will of Fire',headline:'The Will of <em>Fire.</em>',anime:'NARUTO',ink:'木ノ葉',description:'Build your team. Master your Jutsu. Write your own shinobi story.',portrait:'art/identity/naruto-hero.jpg',rival:'art/identity/naruto-hero.jpg',back:'art/identity/naruto-back.jpg',hero:'shadow_clone_technique',troop:'Shinobi',spell:'Jutsu',exp:'01'},
 [STRAW_HATS]:{badge:'☠',short:'One Piece',title:'Set Sail for Adventure',headline:'Set sail for <em>Adventure.</em>',anime:'ONE PIECE',ink:'海賊王',description:'Gather your Nakama. Awaken your powers. Chase the freedom of the open sea.',portrait:'art/identity/one-piece-hero.jpg',rival:'art/identity/one-piece-hero.jpg',back:'art/identity/one-piece-back.jpg',hero:'op_nakama',troop:'Pirates',spell:'Spells',exp:'02'},
};
const meta=(f=faction)=>FACTION_META[f];
function persistDeck(){deckBooks[faction]=[...deck];save('decks',deckBooks);if(faction===LEAF)save('deck',deck);}
function setFaction(f){if(!PLAYABLE_FACTIONS.includes(f))return;activeDeck=null;deckNameDraft=`${f} deck`;save('active-deck',null);persistDeck();faction=f;save('faction',f);presets=ANIME_PRESETS[f];collection=FACTION_POOLS[f].map(getCard);deck=[...(deckBooks[f]??Object.values(presets)[0])];filter='all';search='';mana='all';heroPathView=null;selected=null;zoom=null;zoomUnit=null;render(true);}
function workingDeck(){return{faction,cards:deck,hero:selectedTGHero()};}
function savedDeckOptions(all=false){return savedDecks.filter(d=>all||d.faction===faction).map(d=>`<option value="${d.id}" ${activeDeck===d.id&&(!all||sameDeck(d,workingDeck()))?'selected':''}>${esc(d.name)}${all?' · '+esc(d.faction):''}${d.faction===TOKYO_GHOUL?' · '+esc(TG_HEROES[d.hero??'kaneki']?.name??'Ken Kaneki'):''}${singleDeckProblem(d.faction,d.cards)?' · Draft':''}</option>`).join('');}
function deckLibraryHTML(){const current=savedDecks.find(d=>d.id===activeDeck),dirty=!sameDeck(current,workingDeck());return `<section class="saved-deck-tools"><label>SAVED DECKS<select id="saved-deck"><option value="" ${!current?'selected':''}>Current working deck</option>${savedDeckOptions()}</select></label><label>DECK NAME<input id="deck-name" maxlength="60" value="${esc(deckNameDraft)}"></label><small>${current?dirty?'Unsaved changes':'Saved in this browser':'Save this deck to your library'}</small><div><button data-save-deck>Save deck</button><button class="ghost" data-copy-deck>Save as new</button>${current?'<button class="ghost" data-delete-deck>Delete</button>':''}</div></section>`;}
function storeWorkingDeck(copy=false){const name=$('#deck-name')?.value??`${meta().short} deck`,id=copy?null:activeDeck,newId=crypto.randomUUID();savedDecks=saveDeck(savedDecks,{id,name,...workingDeck()},newId);activeDeck=id??newId;deckNameDraft=name.trim()||'Untitled deck';save('saved-decks',savedDecks);save('active-deck',activeDeck);render(true);toast('Deck and Hero saved.');}
function loadNamedDeck(id){const entry=savedDecks.find(d=>d.id===id);if(!entry)return;const setup=showBattleSetup;setFaction(entry.faction);deck=[...entry.cards];if(entry.faction===TOKYO_GHOUL){tgHero=entry.hero??'kaneki';save('tg-hero',tgHero);}activeDeck=id;deckNameDraft=entry.name;heroPathView=null;showBattleSetup=setup;save('active-deck',id);persistDeck();render(true);toast(`${entry.name} loaded.`);}
function deleteNamedDeck(){const entry=savedDecks.find(d=>d.id===activeDeck);if(!entry)return;const shade=document.createElement('div');shade.className='modal-shade';shade.innerHTML=`<section class="modal"><h2>Delete ${esc(entry.name)}?</h2><p>Your current working cards remain available.</p><button data-delete-confirm>Delete saved deck</button><button class="ghost" data-delete-cancel>Cancel</button></section>`;document.body.append(shade);shade.querySelector('[data-delete-cancel]').onclick=()=>shade.remove();shade.querySelector('[data-delete-confirm]').onclick=()=>{savedDecks=savedDecks.filter(d=>d.id!==entry.id);activeDeck=null;save('saved-decks',savedDecks);save('active-deck',null);shade.remove();render();};}
function factionPicker(){return `<div class="faction-picker" role="group" aria-label="Choose faction">${PLAYABLE_FACTIONS.map(f=>`<button data-faction="${f}" class="${f===faction?'picked':''}" aria-pressed="${f===faction}"><img src="${meta(f).portrait}" alt=""><span>${meta(f).badge} ${f}<small>${meta(f).anime} · ${FACTION_POOLS[f].length} cards</small></span></button>`).join('')}</div>`;}
let page='collection', search='', filter='all', mana='all', rarity='all', sort='number', selected=null, zoom=null;
const boardPreferences=load('board-preferences',{});let boardOrientation=load('board-orientation','auto'),boardSound=load('board-sound',false),boardDebug=false,boardQuality=load('board-quality','auto'),assetTab='boards';
let state=load('match',null), aiTimer=null, toastTimer=null, mulligan=[];
if(state && (!Array.isArray(state.players) || state.players.length!==2 || !state.rules || !Array.isArray(state.queue) || state.players.some(p=>p.factions?.length!==1||!PLAYABLE_FACTIONS.includes(p.factions[0])||!Array.isArray(p.board)||!Array.isArray(p.hand))))state=null;

if(state&&tgRestoreHeroSpells(state))save('match',state);

const counts=()=>deck.reduce((o,id)=>(o[id]=(o[id]??0)+1,o),{});
function toast(message){clearTimeout(toastTimer);let el=$('#toast');if(!el){el=document.createElement('div');el.id='toast';el.setAttribute('role','status');document.body.append(el);}el.textContent=message;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),3000);}
function header(){return `<aside class="sidebar"><a class="brand" href="#collection" aria-label="Anime Clash home"><span class="brand-mark">忍</span><span>ANIME<span>CLASH<span class="brand-dot">.</span></span></span></a><div class="season">THE FIRST CHAPTER <i>01</i></div><nav>${[['collection','Collection'],['decks','Deck builder'],['battle','Battle'],['boards','Boards'],['rules','How to play']].map(([id,label])=>`<a href="#${id}" class="nav-item ${page===id?'active':''}"><span>${icon[id]}</span>${label}${id==='collection'?`<small>${Object.values(FACTION_POOLS).reduce((n,pool)=>n+pool.length,0)}</small>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="leaf-badge">🍃</div><strong>${meta().title}</strong><p>Three factions. Your adventure.</p><span class="version"><i></i> EXPANSION 01</span></div></aside><header class="topbar"><span class="breadcrumb">PLAY / <b>${page==='decks'?'DECK BUILDER':page==='battle'?'BATTLE':page==='rules'?'FIELD GUIDE':page==='boards'?'BOARDS':'COLLECTION'}</b></span><span class="top-right"><span class="status-dot"></span> All cards unlocked <span class="avatar">忍</span></span></header>`;}
function card(c,{builder=false,compact=false,inst=null,valid=false}={}) {
 const frameMeta=frameFor(c),typeLines=minionTypeLines(c);const n=counts()[c.id]??0,type=c.type==='minion'?'minion':c.quickPlay?'quickplay':'spell',frame=c.legendary?`legendary-${c.type}`:`painted-${type}`;
 const df=c.devilFruitUser?'Devil Fruit User · Cannot consume another Fruit':c.devilFruitSpell?'Permanent Fruit · Non-users only':'';
 return `<article class="card ${c.legendary?'legendary':''} ${compact?'compact':''} ${valid?'playable':''}" ${builder?`data-build-card="${c.id}"`:''} ${inst?`data-hand="${inst.uid}" tabindex="0" role="button" aria-label="Play ${esc(c.name)}"`:''}><div class="realm-card new-skin ${c.type==='minion'||c.frameType==='minion'?'minion-frame':'spell-frame'} ${typeLines.length?`typed-minion ${frameMeta.type?'has-type-plaque':'legacy-type-plaque'}`:''}" style="${frameVars(frameMeta)}">
 <div class="card-art" style="background-image:url('${c.image??'art/hidden-leaf/shadow_clone.webp'}')"></div><div class="rules-parchment"><p>${richText(c.text)}</p></div><img class="realm-frame" src="${frameMeta.src}" alt="" draggable="false" loading="lazy"><span class="mana-orb">${c.investigatorHero?'H':c.cost}</span><span class="faction-sigil" title="${esc(c.faction)}">${meta(c.faction)?.badge??'✦'}</span><h3><span class="card-name-text">${esc(c.name)}</span></h3>${typeLines.length?`<div class="minion-types lines-${typeLines.length}" aria-label="Minion types: ${esc(typeLines.join(', '))}">${typeLines.map(line=>`<span>${esc(line)}</span>`).join('')}</div>`:`<div class="card-kind">${c.legendary?'LEGENDARY ':''}${c.token?'TOKEN':c.heroSpell?'HERO SPELL':c.devilFruitSpell?'DEVIL FRUIT':c.type==='minion'?c.faction===LEAF?'SHINOBI':c.faction===TOKYO_GHOUL?c.species:'PIRATE':c.quickPlay?'QUICK PLAY':c.weather?'WEATHER':c.fire?'FIRE SPELL':'SPELL'}</div>`}${['minion','weapon'].includes(c.type)?`<span class="card-atk">${c.attack}</span><span class="card-hp" title="${c.type==='weapon'?'Durability':'Health'}">${c.health??c.durability}</span>`:''}<button class="art-inspect" data-zoom="${c.id}" aria-label="Inspect ${esc(c.name)}">+</button></div>${df?`<div class="fruit-label" title="${esc(df)}">${c.devilFruitUser?'◈ FRUIT USER':'✦ PERMANENT FRUIT'}</div>`:''}${builder?`<div class="card-edit"><button data-remove="${c.id}" aria-label="Remove ${esc(c.name)}" ${n===0?'disabled':''}>−</button><span>${n} / ${copyLimit(c.id)}</span><button data-add="${c.id}" aria-label="Add ${esc(c.name)}" ${n>=copyLimit(c.id)||deck.length>=30?'disabled':''}>+</button></div>`:''}</article>`;
}

function hero(){return `<section class="hero" style="--faction-portrait:url('${new URL(meta().portrait,document.baseURI).href}')"><div class="hero-ink">${meta().ink}</div><div class="hero-content"><div class="eyebrow"><span></span>${meta().anime} · COLLECTION ${meta().exp}</div><h1>${meta().headline}</h1><p>${meta().description}</p><div class="hero-buttons"><button class="primary" data-nav="decks">${faction===TOKYO_GHOUL?'Choose your Hero & deck':'Build your deck'} <span>→</span></button><button class="ghost" data-nav="battle">Enter the battlefield →</button></div></div><div class="hero-label"><span>${meta().badge}</span><div>${faction.toUpperCase()}<small>ONE FACTION. YOUR STRATEGY.</small></div></div></section>`;}

function filters(){return `<div class="collection-tools"><div class="tabs" role="group" aria-label="Card type">${[['all','All cards'],['minion',meta().troop],['spell',meta().spell],...(faction===TOKYO_GHOUL?[['trap','Traps'],['weapon','Quinques']]:[]),['legendary','Legendaries'],['tokens','Tokens']].map(([id,n])=>`<button class="${filter===id?'selected':''}" data-filter="${id}">${n}</button>`).join('')}</div><div class="search-box"><span>⌕</span><input id="search" type="search" placeholder="Find a card or ability…" aria-label="Find a card or ability" value="${esc(search)}"><kbd>/</kbd></div></div><div class="sub-tools"><div class="mana-filter"><span>MANA</span><button data-mana="all" class="${mana==='all'?'on':''}">All</button>${[0,1,2,3,4,5,6,7].map(n=>`<button data-mana="${n}" class="${String(n)===mana?'on':''}">${n===7?'7+':n}</button>`).join('')}</div><label class="sort-label">Sort by <select id="sort" aria-label="Sort cards"><option value="number" ${sort==='number'?'selected':''}>Collection order</option><option value="mana" ${sort==='mana'?'selected':''}>Mana cost</option><option value="name" ${sort==='name'?'selected':''}>Name</option></select></label></div>`;}
function filtered(){let list=(filter==='tokens'?allCards().filter(c=>c.token&&c.faction===faction):collection).filter(c=>(filter==='all'||filter==='tokens'||(filter==='legendary'?c.legendary:c.type===filter))&&(mana==='all'||(mana==='7'?c.cost>=7:c.cost===Number(mana)))&&`${c.name} ${c.text} ${minionTypeLines(c).join(' ')} ${c.legendary?'Legendary':''} ${c.weather?'Weather':''} ${c.fire?'Fire':''} ${c.devilFruitSpell?'Permanent Devil Fruit':''} ${c.luffy?'Luffy Gear Shift':''}`.toLowerCase().includes(search.toLowerCase()));if(sort==='mana')list.sort((a,b)=>a.cost-b.cost||a.name.localeCompare(b.name));if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));return list;}
function collectionHTML(builder=false){const list=filtered();return `${factionPicker()}${builder?heroChooser():''}${!builder?hero():''}<section class="collection-heading"><div><div class="eyebrow">${builder?'YOUR STRATEGY STARTS HERE':'YOUR FACTION COLLECTION'}</div><h2>${builder?'Build your legacy.':faction} <span class="count-pill">${builder?`${deck.length}/30`:`${collection.length} CARDS`}</span></h2><p>${builder?'Choose 30 cards. Up to 2 copies of ordinary cards, 1 of each Legendary.':'Choose your faction. Build a collection around your playstyle.'}</p></div>${!builder?`<div class="collection-stats"><span><b>${collection.filter(c=>c.type==='minion').length}</b>MINIONS</span><span><b>${collection.filter(c=>c.type==='spell').length}</b>SPELLS</span><span><b>${collection.filter(c=>c.legendary).length}</b>LEGENDARY</span></div>`:''}</section><div class="${builder?'builder-layout':''}"><section class="library">${filters()}<div class="results-label"><span>${list.length} ${filter==='tokens'?'generated tokens':'cards'} ${search?'found':'in collection'}</span><span><i class="gold-dot"></i> ${filter==='tokens'?'Tokens cannot be added to decks':`All ${collection.length} cards available to build with`}</span></div><div class="card-grid ${builder?'builder-grid':''}">${list.length?list.map(c=>card(c,{builder:builder&&filter!=='tokens'})).join(''):'<div class="empty-state">No cards match these filters.<button data-reset-filters>Clear filters</button></div>'}</div></section>${builder?deckPanel():''}</div>`;}
function deckPanel(){const ct=counts(),valid=!singleDeckProblem(faction,deck),curve=Array.from({length:8},(_,i)=>deck.filter(id=>i===7?getCard(id).cost>=7:getCard(id).cost===i).length),max=Math.max(1,...curve);return `<aside class="deck-panel"><div class="deck-cover"><span>${meta().badge}</span><h3>Your ${meta().short} deck</h3><p>30 cards · Single faction</p></div><div class="deck-inner">${deckLibraryHTML()}<div class="deck-drop-hint">Drag a card here to add it. On phones, hold a card, then drag.</div><label>START WITH A STRATEGY<select id="preset"><option value="">Choose a starter deck…</option>${Object.keys(presets).map(n=>`<option>${n}</option>`).join('')}</select></label><div class="deck-count"><strong>${deck.length}<small> / 30</small></strong><span class="${valid?'valid':'incomplete'}">${valid?'✓ Ready for battle':'Select your cards'}</span></div><div class="deck-progress"><i style="width:${Math.min(deck.length/30*100,100)}%"></i></div><div class="mana-curve" aria-label="Mana curve">${curve.map((n,i)=>`<div title="${i===7?'7+':i} Mana: ${n} cards"><b>${n||''}</b><i style="height:${n/max*44+2}px"></i><small>${i===7?'7+':i}</small></div>`).join('')}</div><details class="deck-contents" ${deckListOpen?'open':''}><summary>Your cards (${deck.length})</summary><div class="deck-list">${Object.keys(ct).sort((a,b)=>getCard(a).cost-getCard(b).cost).map(id=>{const c=getCard(id);return `<div class="deck-row"><span>${c.cost}</span><button data-zoom="${id}">${esc(c.name)}</button><b>${c.legendary?'✦':`×${ct[id]}`}</b><button data-remove="${id}" aria-label="Remove ${esc(c.name)}">−</button></div>`;}).join('')||'<p class="empty-deck">Add cards from the collection to shape your strategy.</p>'}</div></details><button class="primary full" data-start ${valid&&heroReady()?'':'disabled'}>Play this deck <span>⚔</span></button><div class="deck-actions"><button data-clear>Clear deck</button><button data-export>Export</button><button data-import>Import</button></div></div></aside>`;}
function rulesHTML(){return `<section class="guide-page"><div class="eyebrow">FIELD GUIDE</div><h1>Every legend<br>starts with a <em>team.</em></h1><p class="intro">A familiar battlefield. A new world of anime.</p><div class="rules-grid">${[['01','Choose your faction','Each deck belongs to one anime faction or group. Choose Naruto, One Piece or Tokyo Ghoul. Each has a separate collection and Hero Spell.'],['02','Build a 30-card deck','Choose from your faction’s collectibles. Include up to 2 copies of an ordinary card and 1 copy of each Legendary. Tokens and Hero Spells stay outside your deck.'],['03','Take the battlefield','Heroes begin with 30 Health. Gain a Mana crystal each turn, up to 10. Play minions, cast Jutsu, and attack to bring the opposing Hero to 0. Your board holds 7 minions.'],['04','React with Quick Play','Palm Rotation can defend your Hero or a minion against an enemy attack or targeted spell. Substitution Jutsu and Flying Thunder God Technique protect minions. A reaction pauses combat until you respond or pass. As in the original engine, off-turn Quick Plays cost 1 less (minimum 1) and can borrow Mana from your next turn.'],['05','Use your Hero Spell','Each faction has its own 2-Mana Hero Spell, usable once per turn: Naruto’s Hero Spell summons a Shadow Clone; Nakama! buffs an ally and can heal your Hero.'],['06','Find your synergy','Build around Team 7, Luffy’s Gear evolution, permanent Devil Fruit powers, a crew of Straw Hats, or Tokyo Ghoul’s Hunger, Cannibalism and Quinque arsenal. Use the faction selector to explore all three collections.']].map(([n,h,t])=>`<article><span>${n}</span><h3>${h}</h3><p>${t}</p></article>`).join('')}</div><h2>Know your techniques</h2><div class="keywords">${Object.entries({Jammed:'A Jammed crystal cannot be used on its owner’s next turn. Crystals refill normally the following turn. Jammed Mana cannot be borrowed for Quick Plays.', 'Naruto teams':'Once per team per player per game, controlling the full roster permanently grants those teammates +3/+3 and summons its mentor from your hand (first) or deck if there is room. This does not trigger Arrival. Team 7: Naruto, Sasuke, Sakura → Kakashi. Team Guy: Neji, Rock Lee, Tenten → Might Guy. Team 8: Shino, Hinata, Kiba, Akamaru → Kurenai. Ino–Shika–Cho: Shikamaru, Ino, Choji → Asuma.', Arrival:'Activates when played from hand. Summoned copies do not trigger Arrival.',Taunt:'Enemies must attack a Taunt minion before other characters.',Rush:'Can attack minions immediately, but must wait a turn to attack a Hero.',Evade:'Prevents the first instance of damage, then disappears.',Poisonous:'When this minion dies, the enemy that killed it dies too. This follows the original Shattered Realms keyword.',Freeze:'Cannot attack until it misses its controller’s next turn.',Legendary:'You may include at most one copy in your deck.', 'Gear Shift':'Once per turn after Luffy’s summon turn. Damage, permanent buffs, and attacks used carry over. Gear 4 branches; Gear 5 lasts three own turns, then reverts at 1 Health and rests one turn.', Hunger:'Ghouls and Half-Ghouls gain 1 Hunger at their own turn end unless they consumed this turn. At 3 or more, take 1 starvation damage. Feed costs 1 Mana and your attacks for the turn.', Cannibalism:'A Ghoul Hero gains stacks when an ally consumes a Ghoul or Half-Ghoul, up to 4. Spend 4 Mana and 4 stacks to awaken once per game and choose a second Kagune.', 'Investigator Hero':'Include one Arima, Amon or Akira Hero card in your 30-card deck to select that Hero. It starts outside the draw pile. A generic Investigator can be chosen without a Hero card.', 'Devil Fruit':'Only a non-user may consume a Fruit. Its powers and drawbacks survive Silence and keyword removal, but disappear when it leaves play. Gear forms and natural Users cannot consume Fruit.', Petrify:'Cannot attack or use activated abilities through its controller’s next turn.'}).map(([k,v])=>`<div><strong>${k}</strong><p>${v}</p></div>`).join('')}</div><p class="design-note">First-pass card designs · Minato and Hashirama retain your proposed abilities for playtesting. Temporary disabling lasts through the target’s next turn. Team bonuses check whenever the full team is on the battlefield, including summoned teammates; Hiruzen’s +1/+1 is an aura.</p></section>`;}

function themeFor(f){const saved=boardPreferences[f];return BOARD_THEMES[saved]?saved:f===TOKYO_GHOUL&&((page==='battle'&&state?state.players[0].tokyo?.path:TG_HEROES[selectedTGHero()].path)==='investigator')?'cochlea':boardOptions(f)[0];}
function orientationFor(){return boardOrientation==='auto'?(window.innerWidth>window.innerHeight?'landscape':'portrait'):boardOrientation;}
function boardControlsHTML(f=faction){return `<div class="board-controls"><label>Board<select id="board-theme" data-board-faction="${f}">${BOARD_KEYS.map(key=>`<option value="${key}" ${themeFor(f)===key?'selected':''}>${BOARD_THEMES[key].faction} · ${BOARD_THEMES[key].name}</option>`).join('')}</select></label><label>View<select id="board-orientation"><option value="auto" ${boardOrientation==='auto'?'selected':''}>Automatic</option><option value="portrait" ${boardOrientation==='portrait'?'selected':''}>9:16 portrait</option><option value="landscape" ${boardOrientation==='landscape'?'selected':''}>16:9 landscape</option></select></label><label>Effects<select id="board-quality">${['auto','high','low'].map(q=>`<option value="${q}" ${boardQuality===q?'selected':''}>${q==='auto'?'Automatic':q==='high'?'Full effects':'Light effects'}</option>`).join('')}</select></label><button data-board-sound aria-pressed="${boardSound}">${boardSound?'Sound on':'Sound off'}</button>${page==='boards'?`<button data-board-outlines aria-pressed="${boardDebug}">Interaction outlines</button>`:''}</div>`;}
function boardStudioHTML(){const orientation=orientationFor(),key=themeFor(faction);return `<section class="board-studio"><div class="eyebrow">YOUR BATTLEFIELD</div><h1>Bring the board to life.</h1><p>Explore your decks’ worlds. Tap objects around the edges to discover their reactions.</p>${factionPicker()}<div class="tabs"><button data-asset-tab="boards" class="${assetTab==='boards'?'selected':''}">Interactive boards</button><button data-asset-tab="frames" class="${assetTab==='frames'?'selected':''}">Card frames & heroes</button></div>${assetTab==='boards'?`${boardControlsHTML()}<div class="board-stage" data-orientation="${orientation}"><div class="board-art-mount" data-theme="${key}" data-orientation="${orientation}"></div></div><div class="board-help">${BOARD_THEMES[key].name} · ${orientation==='portrait'?'9:16':'16:9'} · Tap the corners. The center stays clear.</div>`:`<div class="portrait-gallery">${PLAYABLE_FACTIONS.map(f=>`<figure><img src="${meta(f).portrait}" alt="${f} Hero portrait"><figcaption>${f}</figcaption></figure>`).join('')}</div><div class="frame-gallery">${Object.entries(CARD_FRAMES).filter(([name])=>!name.endsWith('-weapon')).map(([name,frame])=>{const label=name.replace('one-piece','One Piece').replace('naruto','Naruto').replace('basic','Basic').replaceAll('-',' '),f=name.startsWith('one-piece')?STRAW_HATS:LEAF;return `<figure><button class="frame-sample" data-frame-preview="${name}" style="${frameVars(frame)}" aria-label="Inspect ${label} frame"><img class="sample-hero" src="${meta(f).portrait}" alt=""><img class="sample-overlay" src="${frame.src}" alt="${label} card frame"></button><figcaption>${label}</figcaption></figure>`;}).join('')}</div>`}</section>`;}
function hydrateBoard(){const host=$('.board-art-mount');if(!host){mountScene(null);return;}const scene=mountScene(host,{theme:host.dataset.theme,orientation:host.dataset.orientation,sound:boardSound,debug:boardDebug,quality:boardQuality});scene?.setActivity(page==='battle'&&!!(selected||state?.pending));scene?.ready.catch(()=>{});}

function legal(){return state?getLegalActions(state):[];}
function battleLobby(){const tg=faction===TOKYO_GHOUL?TG_HEROES[selectedTGHero()]:null;return `<section class="battle-lobby"><div class="eyebrow">THE TRAINING GROUNDS</div><h1>Your next chapter<br>begins in <em>battle.</em></h1><p>Take your ${meta().short} deck into a match against a practice rival.</p><section class="battle-deck-select"><label>CHOOSE YOUR DECK<select id="battle-deck"><option value="">Current working deck · ${esc(meta().short)}</option>${savedDeckOptions(true)}</select></label><p>${deck.length} / 30 playable cards${faction===TOKYO_GHOUL?` · Hero: ${esc(TG_HEROES[selectedTGHero()].name)}`:''}</p></section>${heroChooser()}<div class="lobby-card"><div class="lobby-portrait" style="background-image:url('${tg?.image??meta().portrait}')"></div><div><span class="eyebrow">${tg?(tg.path==='ghoul'?'GHOUL HERO':'INVESTIGATOR HERO'):faction.toUpperCase()}</span><h2>${esc(tg?.name??meta().title)}</h2><p>${tg?`Hero Spell: ${esc(getCard(tg.spell).name)}`:'30 Health · 30 cards · 1 Hero Spell'}</p><label class="rival-label">Rival strategy<select id="rival-preset">${PLAYABLE_FACTIONS.map(f=>`<optgroup label="${f}">${Object.keys(ANIME_PRESETS[f]).map(n=>`<option value="${f}|${n}">${n}</option>`).join('')}</optgroup>`).join('')}</select></label><button class="primary" data-start ${singleDeckProblem(faction,deck)||!heroReady()?'disabled':''}>Start practice match <span>⚔</span></button>${singleDeckProblem(faction,deck)?'<p class="form-error">Finish your 30-card deck in the deck builder first.</p>':''}</div></div>${state&&!state.gameOver?'<button class="ghost" data-resume>Resume your saved match →</button>':''}<p class="practice-note">Local practice · Progress saves in this browser</p></section>`;}
function manaDisruptionHTML(pl){
 const pending=pl.mana.jammedNextTurn??0,blocked=state.activePlayer===pl.index?(pl.mana.jammedThisTurn??0):0;
 return `${pending?`<small class="jammed-status">${pending} Jammed next turn</small>`:''}${blocked?`<small class="jammed-status">${blocked} Jammed this turn</small>`:''}${pl.mana.bonusNextTurn?`<small>+${pl.mana.bonusNextTurn} Mana next turn</small>`:''}`;
}
function narutoTeamsHTML(pl){
 if(!pl.factions.includes(LEAF))return '';
 return `<details class="naruto-teams"><summary>Naruto teams · ${pl.narutoTeamsCompleted?.length??0}/4 complete</summary><div>${NARUTO_TEAMS.map(t=>`<article><strong>${esc(t.name)} ${pl.narutoTeamsCompleted?.includes(t.id)?'✓ Complete':''}</strong><p>${t.members.map(id=>`${pl.board.some(m=>m.cardId===id&&m.health>0&&!m.destroyed)?'✓':'○'} ${esc(getCard(id).name)}`).join(' · ')}</p><small>+3/+3 to teammates · summon ${esc(getCard(t.mentor).name)} from hand/deck · once per game</small></article>`).join('')}</div></details>`;
}
function battleHTML(){return battleLobby();}

function renderSharedBattle(){const pl=state.players[0],theme=themeFor(pl.factions[0]);renderRealmsBattle({state:()=>state,active:()=>page==='battle'&&!!state&&!showBattleSetup,legal,act,fit:el=>{fitRulesText(el);fitCardNames(el);},render,toast,inspect:(id,uid)=>{zoomUnit=uid??null;showZoom(id);},mulligan:()=>mulligan,markMulligan:uid=>{mulligan=mulligan.includes(uid)?mulligan.filter(x=>x!==uid):[...mulligan,uid];render();},save:()=>save('match',state),restore:s=>{state=s;save('match',state);render();},concede:()=>{state.gameOver=true;state.winner=1;state.pending=null;save('match',state);render();},setup:()=>{showBattleSetup=true;render();},teams:()=>narutoTeamsHTML(pl),landscape:boardVariant(theme,'landscape').source,portrait:boardVariant(theme,'portrait').source,mount:host=>mountScene(host,{theme,orientation:orientationFor(),sound:boardSound,debug:boardDebug,quality:boardQuality})});driveAI();}
function render(force=false){if(force)clearTimeout(renderAfterScroll);const shared=page==='battle'&&state&&!showBattleSetup;document.body.classList.toggle('sr-battle',!!shared);for(const id of ['anime-base-css','anime-theme-css'])document.getElementById(id).media=shared?'not all':'all';document.getElementById('realms-battle-css').media=shared?'all':'not all';if(shared){renderSharedBattle();return;}stopRealmsBattle();if(!force&&performance.now()<scrollingUntil){clearTimeout(renderAfterScroll);renderAfterScroll=setTimeout(render,Math.max(20,scrollingUntil-performance.now()+30));return;}restoringScroll=true;const scrollY=scrollRoot().scrollTop,handX=$('.hand')?.scrollLeft??0,listY=$('.deck-list')?.scrollTop??0,logOpen=$('.battle-log')?.open??false,teamsOpen=$('.naruto-teams')?.open??false;const focused=document.activeElement?.id, pos=focused==='search'?$('#search')?.selectionStart:null;
 $('#app').innerHTML=`${header()}<main class="main ${page==='battle'?'battle-main':''}">${page==='collection'?collectionHTML():page==='decks'?collectionHTML(true):page==='rules'?rulesHTML():page==='boards'?boardStudioHTML():battleHTML()}<footer><span>ANIME CLASH <b>·</b> THE FIRST CHAPTER</span><span>A new legend begins with you. 🍃</span></footer></main>`;
 if(focused==='search'){$('#search').focus({preventScroll:true});$('#search').setSelectionRange(pos,pos);}bind();hydrateBoard();if($('.hand'))$('.hand').scrollLeft=handX;if($('.deck-list'))$('.deck-list').scrollTop=listY;if($('.battle-log'))$('.battle-log').open=logOpen;if($('.naruto-teams'))$('.naruto-teams').open=teamsOpen;scrollRoot().scrollTop=scrollY;requestAnimationFrame(()=>{restoringScroll=false;});fitCardText();if(zoom)showZoom(zoom);driveAI();
}
function fitCardText(){document.querySelectorAll('.rules-parchment p').forEach(el=>{let size=parseFloat(getComputedStyle(el).fontSize);while(el.scrollHeight>el.clientHeight+1&&size>6){size-=.3;el.style.setProperty('font-size',size+'px','important');}});}
function changeDeck(id,delta){const c=getCard(id);if(!FACTION_POOLS[faction].includes(id))return;const n=counts()[id]??0;if(delta>0&&deck.length>=30){toast('Your deck already has 30 cards. Remove one before adding another.');return;}if(delta>0&&n>=copyLimit(id)){toast(`Maximum ${copyLimit(id)} copies of ${c.name}.`);return;}if(delta<0){const i=deck.indexOf(id);if(i>=0)deck.splice(i,1);}else deck.push(id);persistDeck();render(true);}
function navigate(to){page=to;selected=null;zoom=null;resetPageScroll();render(true);}
function startMatch(){showBattleSetup=false;if(!heroReady()){toast('Choose your Hero to finish switching paths.');return;}const result=checkDeck({format:'single',factions:[faction],deck,...(faction===TOKYO_GHOUL?{hero:selectedTGHero()}:{})});if(result.error){toast(result.error);return;}
 const [rivalFaction,rivalName]=($('#rival-preset')?.value??`${faction}|${Object.keys(presets)[0]}`).split('|');
 state=createGame({players:[{name:'You',factions:[faction],deck:[...deck],...(faction===TOKYO_GHOUL?{hero:selectedTGHero()}:{})},{name:'Practice rival',factions:[rivalFaction],deck:[...ANIME_PRESETS[rivalFaction][rivalName]],...(rivalFaction===TOKYO_GHOUL?{hero:ANIME_PRESET_HEROES[rivalName]??'kaneki'}:{})}],seed:Date.now()});selected=null;mulligan=[];save('match',state);page='battle';location.hash='battle';render();}

async function act(action,meta={}){if(!action||battleBusy())return;try{const shared=page==='battle'&&!showBattleSetup,before=shared?JSON.parse(JSON.stringify(state)):null;if(shared)await beforeBattleAction(state,action,meta);applyAction(state,action);const visual=before?afterBattleAction(before,state,action,meta):null;selected=null;save('match',state);render();await visual?.();driveAI();}catch(error){console.error(error);toast('That action is no longer available. Please choose again.');selected=null;render();}}
function driveAI(){clearTimeout(aiTimer);if(page!=='battle'||showBattleSetup||battleBusy()||!state||state.gameOver||actingPlayer(state)!==1)return;aiTimer=setTimeout(()=>{try{act(chooseAction(state));}catch(e){console.error(e);toast('The rival could not choose an action. Your match is saved.');}},400);}
const KW_WORDS=['Twin Strike','Quinque','Kagune','Hunger','Consume','Kakuja','Cannibalism','Team 7','Team Guy','Team 8','Ino–Shika–Cho','Jammed','Jam','Devil Fruit User','Ignores Taunt','Quick Play','Gear Shift','Lifesteal','Drawback','Elusive','Silence','Stealth','Arrival','Reborn','Freeze','Poison','Taunt','Evade','Burn','Rush','Exit','Jutsu','Weather','Summon','Transform'];
const KW_TRIG=['At the start of your turn','At the end of your turn','at the start of your turn','at the end of your turn','Once per turn','once per turn','Whenever','If'];
const KW_RE=new RegExp(`(${[...KW_WORDS,...KW_TRIG].map(w=>w.replace(/ /g,'\\s')).join('|')})(?![a-z])|([+-]\\d+\\/[+-]\\d+|[+-]\\d+\\s(?:Attack|Health)|\\d+\\s(?:damage|Mana|Health|cards?))`,'g');
const KW_SET=new Set(KW_WORDS);
function richText(text){return esc(text??'').replace(KW_RE,(m,word,num)=>word?`<b class="${KW_SET.has(word.replace(/\s/g,' '))?'kw':'kw-trig'}">${word}</b>`:`<b class="kw-num">${num}</b>`);}
let zoomCards=[];
function showZoom(id){
 const previous=document.querySelector('.inspect-shade'),returnFocus=previous?.returnFocus??document.activeElement;
 if(!previous){const candidates=page==='battle'&&state?[...state.players[0].hand.map(c=>c.cardId),...state.players.flatMap(p=>p.board.map(m=>m.cardId))]:filtered().map(c=>c.id);zoomCards=[...new Set((candidates.includes(id)?candidates:collection.map(c=>c.id)).flatMap(key=>getCard(key).formCards??[key]))];if(!zoomCards.includes(id))zoomCards=[id];}
 previous?.remove();zoom=id;const at=zoomCards.indexOf(id),c=getCard(id),liveUnit=state?.players.flatMap(p=>p.board).find(m=>m.uid===zoomUnit&&m.cardId===id),terms=cardKeywords(c,liveUnit?allKeywords(liveUnit):[]),wrap=document.createElement('div');wrap.className='modal-shade inspect-shade';wrap.returnFocus=returnFocus;
 wrap.innerHTML=`<section class="modal inspect-modal framed-inspect card-reader" role="dialog" aria-modal="true" aria-label="${esc(c.name)}"><button class="modal-close" aria-label="Close card details">×</button><nav class="inspect-navigation" aria-label="Browse cards"><button data-inspect-prev aria-label="Previous card" ${zoomCards.length<2?'disabled':''}>← Previous</button><span>${at+1} / ${zoomCards.length}</span><button data-inspect-next aria-label="Next card" ${zoomCards.length<2?'disabled':''}>Next →</button></nav><div class="inspector-card">${card(c)}</div><aside class="inspector-glossary"><h2>${esc(c.name)}</h2><p>${esc(c.faction)} · ${c.chimera&&c.token?'Alternate weapon form · not a deck card':c.token?'Generated token':c.heroSpell?'Hero Spell':`Deck limit: ${copyLimit(c.id)} ${c.legendary?'copy':'copies'}`}</p>${c.formCards?`<section class="inspect-forms"><h3>Amatsu forms</h3>${c.formCards.map(key=>`<button data-inspect-form="${key}" aria-pressed="${key===id}">${key==='tg_amatsu'?'Whip form':'Piercing form'}</button>`).join('')}</section>`:''}<h3>Keywords & abilities</h3>${terms.length?terms.map(({term,text})=>`<section><h4>${esc(term)}</h4><p>${esc(text)}</p></section>`).join(''):'<p>This card has no special keywords. Its rules are printed on the card.</p>'}${liveUnit?.devilFruit?`<section><h4>Permanent Fruit powers & drawback</h4><p>${esc(getCard('op_'+liveUnit.devilFruit.kind).text)}</p></section>`:''}<small>Swipe the card left or right, or use the arrow keys, to browse.</small></aside></section>`;
 document.body.append(wrap);wrap.querySelector('.art-inspect')?.remove();
 const close=()=>{zoom=null;zoomUnit=null;wrap.remove();if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true});};
 const move=delta=>{if(zoomCards.length<2)return;zoomUnit=null;showZoom(zoomCards[(at+delta+zoomCards.length)%zoomCards.length]);};
 wrap.querySelectorAll('[data-inspect-form]').forEach(el=>el.onclick=()=>{zoomUnit=null;showZoom(el.dataset.inspectForm);});
 wrap.querySelector('.modal-close').onclick=close;wrap.querySelector('[data-inspect-prev]').onclick=()=>move(-1);wrap.querySelector('[data-inspect-next]').onclick=()=>move(1);wrap.onclick=e=>{if(e.target===wrap)close();};
 wrap.addEventListener('keydown',e=>{if(e.key==='Escape'){e.stopPropagation();close();}if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();e.stopPropagation();move(e.key==='ArrowLeft'?-1:1);}if(e.key==='Tab'){const items=[...wrap.querySelectorAll('button:not(:disabled)')];let i=items.indexOf(document.activeElement);i=(i+(e.shiftKey?-1:1)+items.length)%items.length;e.preventDefault();items[i].focus({preventScroll:true});}});
 let touch=null;const face=wrap.querySelector('.inspector-card');face.addEventListener('touchstart',e=>{if(e.touches.length===1)touch={x:e.touches[0].clientX,y:e.touches[0].clientY};},{passive:true});face.addEventListener('touchend',e=>{if(!touch)return;const t=e.changedTouches[0],dx=t.clientX-touch.x,dy=t.clientY-touch.y;touch=null;if(Math.abs(dx)>55&&Math.abs(dx)>Math.abs(dy)*1.4){if(e.cancelable)e.preventDefault();move(dx<0?1:-1);}},{passive:false});
 fitRulesText(wrap);fitCardNames(wrap);wrap.querySelector('.modal-close').focus({preventScroll:true});
}

function bind(){
 document.querySelectorAll('[data-asset-tab]').forEach(el=>el.onclick=()=>{assetTab=el.dataset.assetTab;render(true);});
 document.querySelectorAll('[data-frame-preview]').forEach(el=>el.onclick=()=>{const name=el.dataset.framePreview,frame=CARD_FRAMES[name],shade=document.createElement('div');shade.className='modal-shade';shade.innerHTML=`<section class="modal frame-inspector" role="dialog" aria-modal="true" aria-label="Card frame"><button class="modal-close" aria-label="Close frame">×</button><img src="${frame.src}" alt="${name.replaceAll('-',' ')} card frame"></section>`;document.body.append(shade);shade.querySelector('button').onclick=()=>shade.remove();shade.onclick=e=>{if(e.target===shade)shade.remove();};});
 const theme=$('#board-theme');if(theme)theme.onchange=e=>{boardPreferences[theme.dataset.boardFaction]=e.target.value;save('board-preferences',boardPreferences);render(true);};
 const orientation=$('#board-orientation');if(orientation)orientation.onchange=e=>{boardOrientation=e.target.value;save('board-orientation',boardOrientation);render(true);};
 const quality=$('#board-quality');if(quality)quality.onchange=e=>{boardQuality=e.target.value;save('board-quality',boardQuality);currentScene()?.setQuality(boardQuality);};
 const sound=$('[data-board-sound]');if(sound)sound.onclick=()=>{boardSound=!boardSound;save('board-sound',boardSound);currentScene()?.setSound(boardSound);render(true);};
 const outlines=$('[data-board-outlines]');if(outlines)outlines.onclick=()=>{boardDebug=!boardDebug;currentScene()?.setDebug(boardDebug);render(true);};
 document.querySelectorAll('[data-faction]').forEach(el=>el.onclick=()=>setFaction(el.dataset.faction));
 const contents=$('.deck-contents');if(contents)contents.ontoggle=()=>{deckListOpen=contents.open;};
 document.querySelectorAll('a.nav-item').forEach(el=>el.onclick=e=>{e.preventDefault();const to=el.hash.slice(1);location.hash=to;navigate(to);});
 document.querySelectorAll('[data-nav]').forEach(el=>el.onclick=()=>{location.hash=el.dataset.nav;});
 document.querySelectorAll('[data-filter]').forEach(el=>el.onclick=()=>{filter=el.dataset.filter;render(true);});
 document.querySelectorAll('[data-mana]').forEach(el=>el.onclick=()=>{mana=el.dataset.mana;render(true);});
 document.querySelectorAll('[data-add]').forEach(el=>el.onclick=()=>changeDeck(el.dataset.add,1));
 document.querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>changeDeck(el.dataset.remove,-1));
 document.querySelectorAll('[data-zoom]').forEach(el=>el.onclick=e=>{e.stopPropagation();zoomUnit=null;showZoom(el.dataset.zoom);});
 document.querySelectorAll('[data-start]').forEach(el=>el.onclick=startMatch);
 bindDeckDrag(document.getElementById('app'),{add:id=>changeDeck(id,1),name:id=>getCard(id).name});
 const on=(selector,event,fn)=>{const el=$(selector);if(el)el[event]=fn;};
 on('#deck-name','oninput',e=>{deckNameDraft=e.target.value;});on('#saved-deck','onchange',e=>loadNamedDeck(e.target.value));on('#battle-deck','onchange',e=>loadNamedDeck(e.target.value));on('[data-save-deck]','onclick',()=>storeWorkingDeck());on('[data-copy-deck]','onclick',()=>storeWorkingDeck(true));on('[data-delete-deck]','onclick',deleteNamedDeck);on('[data-battle-setup]','onclick',()=>{showBattleSetup=true;render(true);});
 on('#search','oninput',e=>{search=e.target.value;render(true);});on('#sort','onchange',e=>{sort=e.target.value;render(true);});
 on('#preset','onchange',e=>{if(!presets[e.target.value])return;deck=[...presets[e.target.value]];heroPathView=null;if(faction===TOKYO_GHOUL)heroPathView=TG_HEROES[ANIME_PRESET_HEROES[e.target.value]??'kaneki'].path;persistDeck();render(true);toast('Starter deck loaded. Customize it to make it yours.');});
 on('[data-fill-hero-slot]','onclick',fillHeroSlot);
 on('[data-clear]','onclick',()=>{deck=[];persistDeck();render(true);});
 on('[data-reset-filters]','onclick',()=>{search='';filter='all';mana='all';render(true);});
 document.querySelectorAll('[data-tg-path]').forEach(el=>el.onclick=()=>{heroPathView=el.dataset.tgPath;render(true);});
 document.querySelectorAll('[data-tg-hero]').forEach(el=>el.onclick=()=>chooseTGHero(el.dataset.tgHero));
 on('[data-cancel]','onclick',()=>{selected=null;render(true);});
 on('[data-new-match]','onclick',()=>{state=null;save('match',null);render(true);});on('[data-resume]','onclick',()=>{showBattleSetup=false;render(true);});
 on('[data-export]','onclick',()=>{const blob=new Blob([JSON.stringify({game:'anime-clash',version:2,faction,cards:deck,...(faction===TOKYO_GHOUL?{hero:selectedTGHero()}:{})},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=faction.toLowerCase().replaceAll(' ','-')+'-deck.json';a.click();URL.revokeObjectURL(url);});
 on('[data-import]','onclick',()=>{const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const data=JSON.parse((await input.files[0].text()).replaceAll('Hidden Leaf Village','Naruto').replaceAll('Straw Hat Pirates','One Piece'));const migrated=data.faction===TOKYO_GHOUL?separateLegacyHero(data.cards,data.hero??'kaneki'):{deck:data.cards,removed:false};const error=singleDeckProblem(data.faction,migrated.deck);if(error&&!(migrated.removed&&data.cards.length===30&&migrated.deck.length===29&&error.startsWith('Choose exactly 30 cards'))){toast(error);return;}if(data.faction!==faction)setFaction(data.faction);deck=[...migrated.deck];heroPathView=null;if(data.faction===TOKYO_GHOUL&&TG_HEROES[migrated.hero]){tgHero=migrated.hero;save('tg-hero',tgHero);}persistDeck();render(true);toast(migrated.removed?'Hero separated. Choose one more playable card to complete your deck.':'Deck imported.');}catch{toast('Choose a valid deck JSON file.');}};input.click();});

}
window.addEventListener('hashchange',()=>{const to=location.hash.slice(1);navigate(['collection','decks','battle','boards','rules'].includes(to)?to:'collection');});
window.addEventListener('keydown',e=>{if(e.key==='Escape'){selected=null;zoom=null;document.querySelector('.inspect-shade')?.remove();render();}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)){e.preventDefault();$('#search')?.focus();}});
page=['collection','decks','battle','boards','rules'].includes(location.hash.slice(1))?location.hash.slice(1):'collection';render();

let touchOrigin=null,ignoreClickUntil=0;
// Suppress a swipe's synthetic click, but allow the next deliberate pointer press.
document.addEventListener('pointerdown',()=>{ignoreClickUntil=0;},true);
document.addEventListener('touchstart',e=>{const t=e.touches[0];touchOrigin=t?{x:t.clientX,y:t.clientY}:null;},{passive:true});
document.addEventListener('touchmove',e=>{const t=e.touches[0];if(touchOrigin&&t&&Math.hypot(t.clientX-touchOrigin.x,t.clientY-touchOrigin.y)>10)ignoreClickUntil=Date.now()+350;},{passive:true});
document.addEventListener('click',e=>{if(!document.body.classList.contains('sr-battle')&&Date.now()<ignoreClickUntil){e.preventDefault();e.stopImmediatePropagation();}},true);

// The game owns its scroll container even inside itch.io's non-scrolling iframe.
// Do not prevent any touchstart/touchmove default; Safari needs native panning.
scrollRoot().addEventListener('scroll',()=>{if(!restoringScroll)scrollingUntil=performance.now()+140;},{passive:true});

let boardResizeTimer;window.addEventListener('resize',()=>{clearTimeout(boardResizeTimer);boardResizeTimer=setTimeout(()=>{const host=$('.board-art-mount');if(boardOrientation==='auto'&&host&&host.dataset.orientation!==orientationFor())render();},180);},{passive:true});

// Card rules text always fits inside its parchment: shrink the text a step at a time until it does
// (fonts render a little larger on some phones, which used to push lines above the box).
function fitRulesText(root=document){root.querySelectorAll('.rules-parchment p').forEach(p=>{p.style.fontSize='';const box=p.parentElement;if(!box||!box.clientHeight)return;let size=parseFloat(getComputedStyle(p).fontSize);for(let i=0;i<14&&p.scrollHeight>box.clientHeight+1;i++){size*=.93;p.style.setProperty('font-size',size+'px','important');}});}
function fitCardNames(root=document){root.querySelectorAll('.realm-card h3').forEach(title=>{const text=title.querySelector('.card-name-text');if(!text||!title.clientHeight)return;title.style.removeProperty('font-size');let size=parseFloat(getComputedStyle(title).fontSize);for(let i=0;i<20&&(text.scrollHeight>title.clientHeight||text.scrollWidth>title.clientWidth);i++){size*=.96;title.style.setProperty('font-size',size+'px','important');}});}
let fitQueued=false;const queueFit=()=>{if(document.body.classList.contains('sr-battle')||fitQueued)return;fitQueued=true;requestAnimationFrame(()=>{fitQueued=false;fitRulesText();fitCardNames();});};
new MutationObserver(queueFit).observe(document.body,{childList:true,subtree:true});addEventListener('resize',queueFit);document.fonts?.ready.then(queueFit);
// Collection and deck builder: tapping anywhere on a card opens it big (buttons keep their own jobs).
document.addEventListener('click',e=>{if(e.target.closest('button,a,input,select,.modal'))return;const card=e.target.closest('.card-grid .realm-card, .card-grid .new-skin');const inspect=card?.querySelector('.art-inspect');if(inspect){e.preventDefault();inspect.click();}});
